#!/usr/bin/env python3
"""notes.py - a trivial notes CLI used as spike fixture."""
import argparse
import json
import sys
from pathlib import Path

NOTES_FILE = Path("notes.json")


def load_notes():
    if NOTES_FILE.exists():
        return json.loads(NOTES_FILE.read_text())
    return []


def save_notes(notes):
    NOTES_FILE.write_text(json.dumps(notes, indent=2))


def main():
    parser = argparse.ArgumentParser(description="Trivial notes CLI")
    parser.add_argument("command", choices=["add", "list"])
    parser.add_argument("text", nargs="?", help="note text (for add)")
    args = parser.parse_args()

    notes = load_notes()
    if args.command == "add":
        if not args.text:
            parser.error("add requires note text")
        notes.append({"id": len(notes) + 1, "text": args.text})
        save_notes(notes)
        print(f"added note {len(notes)}")
    else:
        for n in notes:
            print(f"{n['id']}: {n['text']}")


if __name__ == "__main__":
    main()

